    },
    {
      "requirement_id": "KDH-060",
      "methods": [
        "Test"
      ],
      "rationale": "Access control is verified by attempting to access resources belonging to other users using modified identifiers."
    },
    {
      "requirement_id": "KDH-061",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Text alternatives for non-text content are verified by inspecting the HTML markup for alt attributes and ARIA labels."
    },
    {
      "requirement_id": "KDH-062",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Programmatic determination of structure is verified by inspecting the HTML markup for semantic elements and ARIA roles."
    },
    {
      "requirement_id": "KDH-063",
      "methods": [
