      ],
      "rationale": "Page titles are verified by inspecting the HTML markup for the presence of a <title> element on each page."
    },
    {
      "requirement_id": "KDH-072",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Link purpose clarity is verified by inspecting the HTML markup to ensure link text or aria-labels provide sufficient context."
    },
    {
      "requirement_id": "KDH-073",
      "methods": [
        "Test"
      ],
      "rationale": "Focus visibility is verified by navigating with the keyboard and observing the focus indicator on each interactive element."
    },
    {
      "requirement_id": "KDH-074",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Page language is verified by inspecting the HTML markup for the lang attribute on the <html> element."
    },
    {
      "requirement_id": "KDH-075",
      "methods": [
