      ],
      "rationale": "Language of sections is verified by inspecting the HTML markup for lang attributes on elements containing text in a different language."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik sonlandırılması, sistem üzerinde süre ve koşul senaryoları çalıştırılarak doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Denetim kayıtlarının içerdiği alanların doğruluğu testle, yapısal uygunluğunun ise kayıtların gözle denetlenmesiyle kontrol edilmelidir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Zaman damgalarının UTC formatında ve doğru ayrıntı düzeyinde üretilip üretilmediği testle, kayıtların yapısının ise inceleme ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin algılanması ve uyarı mekanizmasının çalışması, sistem üzerinde saldırı senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Kimlik doğrulama bilgilerinin ekranda gizlenip gizlenmediği, kullanıcı girdisi verildiğinde arayüzün gözlemlenmesiyle test edilmelidir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi içinde yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı, işlem akışı çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test",
        "Analiz"
      ],
      "rationale": "İletişim güvenliğinin sağlandığı ağ trafiği yakalama ile test edilmeli, şifreleme yapılandırmasının yeterliliği ise analiz ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz ve istismar amaçlı girdilerin reddedilmesi, sistem üzerinde çeşitli girdi senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya gösterilen içeriği ve yetkili personele iletilen ayrıntılı logların doğruluğu, hata senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısı, taslak kaydetme ve veri kaybı olmadan devam etme akışının çalışması, sistem üzerinde senaryo çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "CAPTCHA kullanılmadığı ve bot doğrulama akışının çalıştığı testle, erişilebilirlik uyumunun ise inceleme ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edilmesi ve belirsiz durumların yönetimi, entegrasyon senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı doğrulama düzeyinde oturumun sınırlı kipte açılması ve veri gizlenmesi, farklı kimlik belirteçleri ile test edilmelidir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca belirli kullanıcılar için uygulanması ve ele geçirme kanıtında zorunlu değişiklik, senaryo çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilmesi, farklı zaman damgalarıyla kod üretilerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiğinde doğrulayıcının devre dışı bırakılması ve hesap kurtarma akışı, tekrarlı başarısız giriş denemeleriyle test edilmelidir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı AAL düzeylerinde hareketsizlik sonrası yeniden kimlik doğrulama akışlarının ve oturum sırrı yönetiminin çalışması, senaryo çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılması ve bildirim/SIEM iletimi, çoklu oturum senaryolarıyla test edilmelidir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut ve sayı sınırlarının denetlenmesi ve ret mesajlarının içeriği, farklı dosyalar yüklenerek test edilmelidir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-026",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a functional behavior (rejecting short passwords, accepting long ones) that can be verified by executing the system with specific input lengths."
    },
    {
      "requirement_id": "KDH-027",
      "methods": [
        "Test"
      ],
      "rationale": "The character counting logic for Unicode code points can be verified by submitting passwords with specific Unicode characters and observing the system's acceptance or rejection based on length."
    },
    {
      "requirement_id": "KDH-028",
      "methods": [
        "Test"
      ],
      "rationale": "The accessibility of password hints to unauthenticated users can be verified by attempting to access the hint endpoint or UI without authentication."
    },
    {
      "requirement_id": "KDH-029",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The absence of specific UI prompts (security questions) is best verified by inspecting the user interface design and code to ensure no such elements exist."
    },
    {
      "requirement_id": "KDH-030",
      "methods": [
        "Test"
      ],
      "rationale": "The system's handling of full password submission and verification without truncation can be tested by submitting long passwords and verifying the authentication logic."
    },
    {
      "requirement_id": "KDH-031",
      "methods": [
        "Test"
      ],
      "rationale": "The blocklist comparison functionality can be verified by attempting to set a password known to be on the blocklist and observing the rejection."
    },
    {
      "requirement_id": "KDH-032",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to compare the entire password rather than substrings can be tested by using a password that contains a blocked substring but is not itself on the blocklist."
    },
    {
      "requirement_id": "KDH-033",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection message and requirement to select a different password can be verified by submitting a blocked password and observing the system's response."
    },
    {
      "requirement_id": "KDH-034",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The presence of guidance on the UI after a rejection can be demonstrated by triggering the rejection and observing the displayed guidance."
    },
    {
      "requirement_id": "KDH-035",
      "methods": [
        "Test"
      ],
      "rationale": "The compatibility with password managers and autofill can be verified by using a browser's autofill feature or a password manager extension to fill the fields."
    },
    {
      "requirement_id": "KDH-036",
      "methods": [
        "Test"
      ],
      "rationale": "The recovery mechanisms (recovery codes, authenticator, identity proofing) can be tested by simulating account recovery scenarios with different credential combinations."
    },
    {
      "requirement_id": "KDH-037",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of an authenticator after 50 consecutive failures can be verified by performing 50 failed login attempts and then attempting a correct login."
    },
    {
      "requirement_id": "KDH-038",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of multiple authenticators involved in consecutive failures can be tested by failing authentication using multiple factors and verifying their status."
    },
    {
      "requirement_id": "KDH-039",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to re-bind a disabled authenticator can be verified by disabling an authenticator and then attempting to use it without re-binding, followed by re-binding and using it."
    },
    {
      "requirement_id": "KDH-040",
      "methods": [
        "Test"
      ],
      "rationale": "The handling of e-Devlet responses that do not meet security levels can be tested by simulating such responses and observing the system's defined mechanism (decline or route)."
    },
    {
      "requirement_id": "KDH-041",
      "methods": [
        "Test"
      ],
      "rationale": "The session AAL handling can be verified by creating a session at a specific AAL and attempting to access resources that require a higher AAL, ensuring the session is not treated as higher than its creation level."
    },
    {
      "requirement_id": "KDH-042",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of fallback to insecure transport can be tested by attempting to downgrade an HTTPS session to HTTP and observing the system's rejection."
    },
    {
      "requirement_id": "KDH-043",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The implementation of automated attack protections (bot detection, WAF, etc.) is best verified by reviewing the configuration, code, and security architecture documents."
    },
    {
      "requirement_id": "KDH-044",
      "methods": [
        "Test"
      ],
      "rationale": "The one-time use of a TOTP code can be verified by using a valid TOTP code for authentication and then attempting to use the same code again."
    },
    {
      "requirement_id": "KDH-045",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of a recovery notification when a new recovery code is issued can be verified by issuing a new code and checking for the notification."
    },
    {
      "requirement_id": "KDH-046",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of a used recovery code and issuance of a new one can be verified by using a recovery code and then attempting to use it again, while checking for the new code."
    },
    {
      "requirement_id": "KDH-047",
      "methods": [
        "Test"
      ],
      "rationale": "The restriction of access to AAL2 or AAL3 can be verified by attempting to access account information with lower AAL authentication and observing the denial."
    },
    {
      "requirement_id": "KDH-048",
      "methods": [
        "Test"
      ],
      "rationale": "The notification of account updates can be verified by making a change to the account information and checking for the notification."
    },
    {
      "requirement_id": "KDH-049",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The capability to report unauthorized access can be demonstrated by navigating to the reporting feature and submitting a report."
    },
    {
      "requirement_id": "KDH-050",
      "methods": [
        "Test"
      ],
      "rationale": "The return of generic error messages without internal details can be verified by triggering security-sensitive errors and inspecting the response for sensitive information."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the availability of specific authentication options, which is verified by executing the login flow and observing the presented choices."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system's behavior of enforcing multi-factor or two-factor authentication is verified by attempting logins with different factor combinations and observing the acceptance or rejection."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Periodic reauthentication based on inactivity and overall timeouts is verified by simulating user inactivity and session duration to observe the system's reauthentication prompts."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of notifications upon account recovery is verified by triggering a recovery process and observing the delivery of the notification to the designated recipient."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The distribution of notifications to registered addresses (excluding postal) is verified by triggering a notification event and checking which registered channels receive the message."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The independence of the VBP session from the e-Devlet assertion validity window is verified by maintaining a VBP session after the e-Devlet assertion expires and observing continued access."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The content of the assertion request, specifically the inclusion of the VBP identifier and cryptographic nonce, is verified by inspecting the network traffic or code implementation of the federation transaction."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion audience is verified by attempting to inject an assertion generated for a different relying party and observing that VBP rejects it."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The enforcement of the binding process for changing the SMS telephone number is verified by attempting to change the number and observing that the specific binding authentication steps are required."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to bind multiple authenticators is verified by adding more than one authenticator to an account and observing that the system allows and stores them."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The authentication level required for binding a new authenticator is verified by initiating the binding process with different existing account AAL levels and observing the required authentication strength."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The independent notification mechanism upon adding an authenticator is verified by adding a new authenticator and observing the delivery of a notification via a channel separate from the binding transaction."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of the confirmation code after successful use is verified by using the code once and then attempting to reuse it within the validity period, expecting rejection."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion signature is verified by presenting an assertion with an invalid or tampered signature and observing that VBP rejects it."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "Replay protection is verified by submitting the same valid e-Devlet assertion twice and observing that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The initiation of the federation transaction by VBP as the RP is verified by inspecting the sequence of network requests or the code logic to confirm VBP initiates the flow."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of information leakage during proofing is verified by submitting incorrect self-asserted information and observing that the error message does not reveal which specific attribute failed verification."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
