    {
      "id": "TC-092-01",
      "title": "Verification of calculation assumptions for PBD speed restriction",
      "covers": [
        "ETC-092"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is configured with known parameters for rotating mass, safe/expected deceleration, and fixed assumptions (T41, T_bs1, T_bs2, T_traction, V_delta0).",
      "test_inputs": "A PBD profile with a specific gradient and PBD distance. Trackside data includes adhesion profiles and brake-inhibition conditions (which should be ignored).",
      "assumptions": "The OBU's internal calculation parameters are accessible or verifiable via logs/analysis.",
      "steps": [
        {
          "no": 1,
          "action": "Send a PBD profile with a non-zero gradient and trackside data containing adhesion profiles and brake-inhibition conditions.",
          "expected": "The OBU uses the rotating-mass-compensated gradient value for the calculation."
        },
        {
          "no": 2,
          "action": "Verify the deceleration curves used in the calculation.",
          "expected": "The safe deceleration curve ignores trackside adhesion profiles and brake-inhibition/powerless-section conditions. The expected deceleration curve ignores brake-inhibition/powerless-section conditions."
        },
        {
          "no": 3,
          "action": "Verify the EBD and SBD curves (if service brake is selected).",
          "expected": "The EBD curve reaches zero speed at the permitted braking distance. If service brake is selected, the SBD curve also reaches zero speed at the permitted braking distance."
        },
        {
          "no": 4,
          "action": "Verify the fixed assumptions used in the calculation.",
          "expected": "Estimated acceleration is set to zero. Speed-inaccuracy compensation, processing delay (T41), brake feedback (T_bs1, T_bs2), and traction cut-off (T_traction) are applied as fixed values per SUBSET-026 §3.11.11.4, regardless of actual configuration."
        }
      ]
