      "preconditions": "A company representative account exists with both a password and a second-factor authenticator (e.g., OTP) bound. The account is currently active and not locked.",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The threshold for consecutive failed attempts defined in VBP Software Design Document §14 is 5 for this test scenario.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an invalid password, and an invalid second-factor code.",
          "expected": "Authentication fails. The system records the failure for both the password and the second-factor authenticator."
        },
        {
          "no": 2,
          "action": "Repeat the failed login attempt with invalid credentials for a total of 4 consecutive failures.",
          "expected": "Authentication fails each time. The account remains active, and no authenticators are disabled."
        },
        {
          "no": 3,
          "action": "Perform the 5th consecutive failed login attempt with invalid password and invalid second-factor code.",
          "expected": "Authentication fails. The system disables both the password authenticator and the second-factor authenticator for the account."
        },
        {
          "no": 4,
          "action": "Attempt login with the correct password and a valid second-factor code.",
          "expected": "Login is rejected. The system indicates that the authenticators are disabled and require re-binding."
        }
      ]
    },
    {
      "id": "TC-KDH-038-02",
      "title": "Authenticators remain active below threshold",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists with both a password and a second-factor authenticator bound. The account is active.",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The threshold for consecutive failed attempts defined in VBP Software Design Document §14 is 5 for this test scenario.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the valid username, an invalid password, and an invalid second-factor code.",
          "expected": "Authentication fails. The system records the failure."
        },
        {
          "no": 2,
          "action": "Attempt login again with the valid username, an invalid password, and an invalid second-factor code.",
          "expected": "Authentication fails. The system records the second failure."
        },
        {
          "no": 3,
          "action": "Attempt login with the correct password and a valid second-factor code.",
          "expected": "Login is successful. The account remains active, and both authenticators remain enabled."
        }
      ]
    }
  ]
