      "assumptions": "The system logs the AAL of the authentication event and the resulting session AAL for verification purposes.",
      "steps": [
        {
          "no": 1,
          "action": "Authenticate the user using AAL1 credentials.",
          "expected": "Authentication succeeds. The system records the session AAL as AAL1."
        },
        {
          "no": 2,
          "action": "Attempt to access a resource that requires AAL2 using the current session.",
          "expected": "Access is denied or a step-up authentication prompt is displayed. The session AAL remains AAL1 and is not automatically elevated to AAL2."
        }
      ]
    },
    {
      "id": "TC-041-02",
      "title": "Session AAL can be lower than authentication event AAL",
      "covers": [
        "KDH-041"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A test user account exists with authentication capabilities for AAL2. The system allows configuring the session AAL to be lower than the authentication AAL (e.g., for low-risk operations).",
      "test_inputs": "Valid credentials for AAL2 authentication. A resource configured to require AAL1.",
      "assumptions": "The system supports a configuration or logic that permits a session to be established at a lower AAL than the authentication event, as permitted by the requirement.",
      "steps": [
        {
          "no": 1,
          "action": "Authenticate the user using AAL2 credentials.",
          "expected": "Authentication succeeds. The authentication event is recorded as AAL2."
        },
        {
          "no": 2,
          "action": "Access a resource that requires AAL1 using the current session.",
          "expected": "Access is granted. The session is treated as AAL1 (or higher) for this resource, which is permitted since the session AAL is not higher than the authentication event AAL."
        }
      ]
    },
    {
      "id": "TC-041-03",
      "title": "Prevention of session AAL elevation without re-authentication",
      "covers": [
        "KDH-041"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A user is authenticated at AAL1. The system has a mechanism to request higher AAL for specific actions.",
      "test_inputs": "Valid AAL1 session. A request to perform an action requiring AAL3.",
      "assumptions": "The system does not have a bug that allows session AAL to be modified directly via API or client-side manipulation without a new authentication event.",
      "steps": [
        {
          "no": 1,
          "action": "Authenticate the user at AAL1.",
          "expected": "Session is established with AAL1."
        },
        {
          "no": 2,
          "action": "Attempt to modify the session AAL to AAL3 via a direct API call or client-side parameter manipulation without providing AAL3 credentials.",
          "expected": "The request is rejected. The session AAL remains AAL1. The system does not treat the session as AAL3."
        }
      ]
    }
  ]
}

