{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "New session token generation and old token invalidation upon re-authentication",
      "covers": [
        "KDH-057"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A valid user account exists. The user is currently authenticated with an active session token (Token A).",
      "test_inputs": "Valid credentials for re-authentication.",
      "assumptions": "The system allows re-authentication while a session is active (e.g., via a 'Change Password' or 'Re-login' flow) or supports multiple concurrent sessions where re-auth creates a new context. The backend session store is inspectable for verification.",
      "steps": [
        {
          "no": 1,
          "action": "Capture the current active session token (Token A) from the user's browser or API response.",
          "expected": "Token A is valid and associated with the user's active session."
        },
        {
          "no": 2,
          "action": "Trigger a re-authentication event for the same user (e.g., log out and log back in, or perform a password change that forces re-login).",
          "expected": "The system accepts the new credentials and establishes a new session."
        },
        {
          "no": 3,
          "action": "Capture the new session token (Token B) issued after re-authentication.",
          "expected": "Token B is generated and is different from Token A."
        },
        {
          "no": 4,
          "action": "Attempt to make an authenticated API request using the old Token A.",
          "expected": "The request is rejected with an authentication error (e.g., 401 Unauthorized), indicating Token A has been terminated/invalidated."
        },
        {
          "no": 5,
          "action": "Attempt to make an authenticated API request using the new Token B.",
          "expected": "The request is successful, confirming Token B is the active session token."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Session invalidation upon user-initiated logout",
      "covers": [
        "KDH-058"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The user is authenticated with an active session token (Token A).",
      "test_inputs": "None",
      "assumptions": "The backend session store is inspectable to verify invalidation status.",
      "steps": [
        {
          "no": 1,
          "action": "Capture the current active session token (Token A).",
          "expected": "Token A is valid."
        },
        {
          "no": 2,
          "action": "Initiate the logout process from the user interface.",
          "expected": "The user is redirected to the login page or a logout confirmation screen."
        },
        {
          "no": 3,
          "action": "Attempt to make an authenticated API request using the previously captured Token A.",
          "expected": "The request is rejected with an authentication error (e.g., 401 Unauthorized), confirming the session data was invalidated at the backend."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Session invalidation upon inactivity timeout expiration",
      "covers": [
        "KDH-058"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The user is authenticated with an active session token (Token A). The system's inactivity timeout is known (e.g., 15 minutes).",
      "test_inputs": "None",
      "assumptions": "The inactivity timeout duration is configurable or known for the test environment. The backend session store is inspectable.",
      "steps": [
        {
          "no": 1,
          "action": "Capture the current active session token (Token A).",
          "expected": "Token A is valid."
        },
        {
          "no": 2,
          "action": "Wait for the inactivity timeout period to elapse without performing any user actions.",
          "expected": "The session expires due to inactivity."
        },
        {
          "no": 3,
          "action": "Attempt to make an authenticated API request using the previously captured Token A.",
          "expected": "The request is rejected with an authentication error (e.g., 401 Unauthorized), confirming the session was terminated and invalidated at the backend upon expiration."
        }
      ]
    },
    {
      "id": "TC-004",
      "title": "Session invalidation upon absolute maximum lifetime expiration",
      "covers": [
        "KDH-058"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The user is authenticated with an active session token (Token A). The system's absolute maximum session lifetime is known (e.g., 8 hours).",
      "test_inputs": "None",
      "assumptions": "The absolute maximum session lifetime is configurable or known for the test environment. The backend session store is inspectable.",
      "steps": [
        {
          "no": 1,
          "action": "Capture the current active session token (Token A).",
          "expected": "Token A is valid."
        },
        {
          "no": 2,
          "action": "Wait for the absolute maximum session lifetime to elapse, performing periodic activity to prevent inactivity timeout.",
          "expected": "The session expires due to reaching the maximum lifetime limit."
        },
        {
          "no": 3,
          "action": "Attempt to make an authenticated API request using the previously captured Token A.",
          "expected": "The request is rejected with an authentication error (e.g., 401 Unauthorized), confirming the session was terminated and invalidated at the backend upon reaching the maximum lifetime."
        }
      ]
    }
  ]
}

